/* ---------- Success / North Star ---------- */

// Baselines = whole company won-book, aggregated per (calendar year, deal-owner motion).
// One query returns 2025 (full year) + 2026 (Jan–Apr only, bounded by the query WHERE)
// so both fixed reference periods come back with correct per-period distinct-account counts.
function baselineFor(motionSel) {
  var out = { b2025: { amt: 0, deals: 0, accts: 0 }, b2026: { amt: 0, deals: 0, accts: 0 } };
  modelArray("baselines").forEach(function (r) {
    var yr = String(r.yr);
    if (yr !== "2025" && yr !== "2026") return;
    if (mapMotion(r.motion) === "Agency") return; // Success KPIs exclude Agency everywhere
    if (motionSel !== "all" && mapMotion(r.motion) !== motionSel) return;
    var b = yr === "2025" ? out.b2025 : out.b2026;
    b.amt += r.amt || 0; b.deals += r.deals || 0; b.accts += r.accts || 0;
  });
  return out;
}
// Qualified-Bestand migration rate from the account universe (independent of the
// Account-View toggles): denominator = active accounts with Bookings_last_12m >= 6k
// under real leadership; numerator = those flagged New_Commercial_Offering__c.
// Agency is excluded — Agency keeps its own pricing and isn't a FULL-FLEX migration target.
function qualMigration() {
  var q = 0, m = 0;
  modelArray("accounts").forEach(function (r) {
    var of = ownerFields(r.Owner);
    if (!hasLeadership(of)) return;
    if (of.motion === "Agency") return;
    if ((r.Bookings_last_12_months__c || 0) >= QUALIFY_MIN) { q++; if (r.New_Commercial_Offering__c === true) m++; }
  });
  return { q: q, m: m };
}
// Jobs (Redshift): active-jobs per SF account. Appsmith custom widgets are sandboxed
// and cannot reach Redshift directly, so this ships as a PRE-AGGREGATED SNAPSHOT
// (JOBS_SNAPSHOT, generated from dds_inventory via top-1 fuzzy match >=0.6, refreshed
// periodically — see JOBS_SNAPSHOT_ASOF). If a live `jobs` model key is ever wired
// (Redshift datasource returning {sf_account_id, active_jobs}), it overlays and wins.
var JOBS_SNAPSHOT_ASOF = "2026-07-31";
