// Week-over-week: reconstruct each opp's stage as of 7 days ago from OpportunityHistory.
function computeWoW(opps) {
  var hist = modelArray("history");
  var byOpp = {};
  hist.forEach(function (h) { (byOpp[h.OpportunityId] || (byOpp[h.OpportunityId] = [])).push(h); });
  Object.keys(byOpp).forEach(function (k) { byOpp[k].sort(function (a, b) { return new Date(a.CreatedDate) - new Date(b.CreatedDate); }); });
  var cutoff = Date.now() - 7 * 86400000;
  function lastWeekStage(o) {
    if (o.created && new Date(o.created).getTime() > cutoff) return null; // new this week
    var rows = byOpp[o.id] || [], st = null;
    for (var i = 0; i < rows.length; i++) { if (new Date(rows[i].CreatedDate).getTime() <= cutoff) st = rows[i].StageName; else break; }
    if (st) return st;
    if (rows.length) return rows[0].StageName;
    return o.stage;
  }
  var lw = {}, tw = {}, zug = {}, abg = {}, neu = {}, neuTotal = 0, wonW = 0, lostW = 0;
  opps.forEach(function (o) {
    var t = o.stage;
    tw[t] = (tw[t] || 0) + 1;
    var l = lastWeekStage(o);
    if (l === null) { neu[t] = (neu[t] || 0) + 1; neuTotal++; }
    else {
      lw[l] = (lw[l] || 0) + 1;
      if (l !== t) { abg[l] = (abg[l] || 0) + 1; zug[t] = (zug[t] || 0) + 1; }
    }
    var rows = byOpp[o.id] || [], last = rows[rows.length - 1];
    if (o.status !== "open" && last && new Date(last.CreatedDate).getTime() > cutoff) { if (o.status === "won") wonW++; else lostW++; }
  });
  var sumLw = 0; Object.keys(lw).forEach(function (k) { sumLw += lw[k]; });
  return { lw: lw, tw: tw, zug: zug, abg: abg, neu: neu, neuTotal: neuTotal, wonW: wonW, lostW: lostW, sumLw: sumLw, sumTw: opps.length };
}
function isoWeek(d) {
  var dt = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  var dayNum = (dt.getUTCDay() + 6) % 7;
  dt.setUTCDate(dt.getUTCDate() - dayNum + 3);
  var firstThu = new Date(Date.UTC(dt.getUTCFullYear(), 0, 4));
  return 1 + Math.round(((dt - firstThu) / 86400000 - 3 + ((firstThu.getUTCDay() + 6) % 7)) / 7);
}
// Reconstruct the stage distribution as of each of the last `weeks` weeks from OpportunityHistory.
function computeTrend(opps, weeks) {
  var hist = modelArray("history");
  var byOpp = {};
  hist.forEach(function (h) { (byOpp[h.OpportunityId] || (byOpp[h.OpportunityId] = [])).push(h); });
  Object.keys(byOpp).forEach(function (k) { byOpp[k].sort(function (a, b) { return new Date(a.CreatedDate) - new Date(b.CreatedDate); }); });
  function stageAsOf(o, cutoff) {
    if (o.created && new Date(o.created).getTime() > cutoff) return null;
    var rows = byOpp[o.id] || [], st = null;
    for (var i = 0; i < rows.length; i++) { if (new Date(rows[i].CreatedDate).getTime() <= cutoff) st = rows[i].StageName; else break; }
    if (st) return st;
    if (rows.length) return rows[0].StageName;
    return o.stage;
  }
  var out = [];
  for (var wk = weeks - 1; wk >= 0; wk--) {
    var cutoff = Date.now() - wk * 7 * 86400000;
    var counts = {};
    opps.forEach(function (o) { var s = stageAsOf(o, cutoff); if (s) counts[s] = (counts[s] || 0) + 1; });
    out.push({ cutoff: cutoff, label: "KW" + isoWeek(new Date(cutoff)), counts: counts });
  }
  return out;
}
function renderTrendChart(trendRaw) {
  // Bucket stages outside the current funnel (opps' earlier life) into "Andere".
  var trend = trendRaw.map(function (w) {
    var c = {}; Object.keys(w.counts).forEach(function (s) { var k = STAGE_ORDER.indexOf(s) >= 0 ? s : "Andere"; c[k] = (c[k] || 0) + w.counts[s]; });
    return { label: w.label, counts: c };
  });
  var order = STAGE_ORDER.concat(["Andere"]);
  var stages = order.filter(function (s) { return trend.some(function (w) { return (w.counts[s] || 0) > 0; }); });
  var maxTotal = 1;
  trend.forEach(function (w) { var t = 0; stages.forEach(function (s) { t += w.counts[s] || 0; }); if (t > maxTotal) maxTotal = t; });
  var W = 1000, H = 300, mL = 40, mR = 12, mT = 12, mB = 28, plotW = W - mL - mR, plotH = H - mT - mB, n = trend.length;
  var bw = (plotW / n) * 0.68;
  var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" preserveAspectRatio="xMidYMid meet">';
  var ticks = 4;
  for (var t = 0; t <= ticks; t++) {
    var y = mT + plotH - (plotH * t / ticks);
    svg += '<line x1="' + mL + '" y1="' + y.toFixed(1) + '" x2="' + (W - mR) + '" y2="' + y.toFixed(1) + '" stroke="#eef0f3"/>';
    svg += '<text x="' + (mL - 6) + '" y="' + (y + 3).toFixed(1) + '" text-anchor="end" font-size="10" fill="#8a94a6">' + Math.round(maxTotal * t / ticks) + '</text>';
  }
  trend.forEach(function (w, i) {
    var cx = mL + plotW * (i + 0.5) / n, x = cx - bw / 2, acc = 0;
    stages.forEach(function (s) {
      var c = w.counts[s] || 0; if (c <= 0) return;
      var h = plotH * c / maxTotal, y = mT + plotH - (plotH * (acc + c) / maxTotal);
      svg += '<rect x="' + x.toFixed(1) + '" y="' + y.toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + h.toFixed(1) + '" fill="' + (STAGE_COLORS[s] || "#8a94a6") + '"><title>' + esc(s) + ' ' + w.label + ': ' + c + '</title></rect>';
      acc += c;
    });
    svg += '<text x="' + cx.toFixed(1) + '" y="' + (H - 8) + '" text-anchor="middle" font-size="9" fill="#8a94a6">' + esc(w.label) + '</text>';
  });
  svg += '</svg>';
  var box = el("div", "");
  box.appendChild(el("div", "trend-title", "Pipeline-Verlauf nach Stage (letzte " + n + " Wochen)"));
  var wrap = el("div", "trend-wrap"); wrap.innerHTML = svg; box.appendChild(wrap);
  var legend = el("div", "trend-legend");
  stages.forEach(function (s) { var it = el("span", "trend-leg-item", '<span class="trend-sw" style="background:' + (STAGE_COLORS[s] || "#8a94a6") + '"></span>' + esc(s)); legend.appendChild(it); });
  box.appendChild(legend);
  box.appendChild(el("div", "trend-note", "Rekonstruiert für die heutige Migrations-Kohorte. Frühe Wochen sind klein, da die meisten Opps erst kürzlich als Migrations-Potential angelegt wurden; „Andere\" = Stages außerhalb des aktuellen Funnels (frühere Opp-Historie)."));
  return box;
}
function renderWoWBody(body, w, opps) {
  body.innerHTML = "";
