    return;
  }
  // multi-week trend chart
  body.appendChild(renderTrendChart(computeTrend(opps, 12)));

  // flow table: Letzte Woche + Zugänge − Abgänge + Neu = Diese Woche
  var stages = STAGE_ORDER.slice();
  ["tw", "lw", "zug", "abg", "neu"].forEach(function (m) { Object.keys(w[m]).forEach(function (s) { if (stages.indexOf(s) < 0) stages.push(s); }); });
  stages = stages.filter(function (s) { return (w.lw[s] || 0) + (w.tw[s] || 0) + (w.zug[s] || 0) + (w.abg[s] || 0) + (w.neu[s] || 0) > 0; });

