  tbl.appendChild(head);
  stages.forEach(function (s) {
    var row = el("div", "flow-row");
    row.appendChild(el("div", "name-txt", esc(s)));
    row.appendChild(el("div", "num", String(w.lw[s] || 0)));
    row.appendChild(el("div", "num flow-in", w.zug[s] ? "+" + w.zug[s] : "·"));
    row.appendChild(el("div", "num flow-out", w.abg[s] ? "−" + w.abg[s] : "·"));
    row.appendChild(el("div", "num flow-new", w.neu[s] ? "+" + w.neu[s] : "·"));
    row.appendChild(el("div", "num count-big", String(w.tw[s] || 0)));
    tbl.appendChild(row);
  });
  var sumZug = 0, sumAbg = 0;
  Object.keys(w.zug).forEach(function (k) { sumZug += w.zug[k]; });
