  tr.appendChild(el("div", "num flow-out", sumAbg ? "−" + sumAbg : "·"));
  tr.appendChild(el("div", "num flow-new", w.neuTotal ? "+" + w.neuTotal : "·"));
  tr.appendChild(el("div", "num count-big", String(w.sumTw)));
  tbl.appendChild(tr);
  body.appendChild(tbl);
  body.appendChild(el("div", "wow-note", "Bewegung der aktuellen Migrations-Opps über die letzten 7 Tage (Stage rekonstruiert aus OpportunityHistory). Zugänge/Abgänge = bestehende Opps, die zwischen Stages gewandert sind (Summe Zugänge = Summe Abgänge); Neu = diese Woche neu angelegt. Auflösung je Stage: Letzte Woche + Zugänge − Abgänge + Neu = Diese Woche."));
}
